/* Ground PV array viewer. The bundled GLB is an approximate reconstruction of the supplied aerial photo. */
(()=>{
'use strict';
const PV_MODEL_BASE64="";

const stage=document.getElementById('pv-model-stage');
const canvas=document.getElementById('pv-glb-canvas');
const reset=document.getElementById('pv-model-reset');
const hint=document.getElementById('pv-model-hint');
if(!stage||!canvas||!reset||!hint)return;
(async()=>{
 const {THREE,GLTFLoader,OrbitControls}=await window.sunroomThreeReady;
 const binary=Uint8Array.from(atob(PV_MODEL_BASE64),letter=>letter.charCodeAt(0));
 const gltf=await new Promise((resolve,reject)=>new GLTFLoader().parse(binary.buffer,'',resolve,reject));
 const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});
 renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.5));
 renderer.setClearColor(0xffffff,0);
 renderer.outputColorSpace=THREE.SRGBColorSpace;
 renderer.toneMapping=THREE.ACESFilmicToneMapping;
 renderer.toneMappingExposure=.86;
 const scene=new THREE.Scene();
 scene.add(new THREE.HemisphereLight(0xffffff,0x9eb59c,.96));
 const key=new THREE.DirectionalLight(0xffffff,1.35);key.position.set(-8,16,10);scene.add(key);
 const fill=new THREE.DirectionalLight(0xdde0ff,.45);fill.position.set(10,8,-8);scene.add(fill);
 const model=gltf.scene;scene.add(model);
 const bounds=new THREE.Box3().setFromObject(model);
 if(bounds.isEmpty())throw new Error('The PV array GLB has no geometry.');
 const center=bounds.getCenter(new THREE.Vector3());
 const camera=new THREE.PerspectiveCamera(32,1,.05,1000);
 const direction=new THREE.Vector3(.16,2.35,1.18).normalize();
 const controls=new OrbitControls(camera,canvas);
 controls.enableDamping=true;controls.dampingFactor=.06;controls.enablePan=false;
 controls.minPolarAngle=.08;controls.maxPolarAngle=Math.PI*.49;
 controls.rotateSpeed=.7;controls.zoomSpeed=.72;
 let interacted=false;
 controls.addEventListener('start',()=>{interacted=true;});
 function fit(){
  const right=new THREE.Vector3().crossVectors(camera.up,direction).normalize();
  const up=new THREE.Vector3().crossVectors(direction,right).normalize();
  const v=Math.tan(THREE.MathUtils.degToRad(camera.fov/2)),h=v*camera.aspect;
  let distance=1;
  for(const x of [bounds.min.x,bounds.max.x])for(const y of [bounds.min.y,bounds.max.y])for(const z of [bounds.min.z,bounds.max.z]){
   const delta=new THREE.Vector3(x,y,z).sub(center);
   distance=Math.max(distance,delta.dot(direction)+1.16*Math.max(Math.abs(delta.dot(right))/h,Math.abs(delta.dot(up))/v));
  }
  camera.far=Math.max(1000,distance*8);camera.updateProjectionMatrix();
  controls.minDistance=distance*.42;controls.maxDistance=distance*2.8;
  controls.target.copy(center);camera.position.copy(center).addScaledVector(direction,distance);controls.update();
 }
 function resize(){
  const {width,height}=stage.getBoundingClientRect();
  if(width<2||height<2)return;
  renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();
  if(!interacted)fit();
  renderer.render(scene,camera);
 }
 reset.addEventListener('click',()=>{interacted=false;fit();renderer.render(scene,camera);});
 canvas.hidden=false;hint.hidden=false;reset.hidden=false;stage.classList.add('glb-ready');
 new ResizeObserver(resize).observe(stage);resize();
 let visible=true;new IntersectionObserver(entries=>{visible=entries[0]?.isIntersecting??true;}).observe(stage);
 function animate(){requestAnimationFrame(animate);if(!visible||document.hidden)return;controls.update();renderer.render(scene,camera);}
 animate();
 stage.dataset.modelLoaded='true';
})().catch(error=>{console.warn('Ground PV GLB could not be displayed; keeping the layout diagram.',error);stage.dataset.modelLoaded='false';});
})();
